/* Illustrative temporal projection. No telemetry or execution is connected. */
const timelinePhases = [
  {id:'plan',name:'Plan',role:'PM · Manager',start:0,end:28,spans:['plan'],children:['context','memory-read','planner']},
  {id:'spec',name:'Spec',role:'PM',start:28,end:58,spans:['spec'],children:['requirements']},
  {id:'design',name:'Design',role:'Designer',start:58,end:83,spans:['design'],children:['designer']},
  {id:'build',name:'Build',role:'Developer',start:83,end:212,spans:['developer','repair'],children:['build-memory','read','edit','memory-write','repair']},
  {id:'verify',name:'Verify',role:'QA · deterministic gates',start:138,end:252,spans:['check-failed','qa'],children:['test-failed','test-running']},
  {id:'review',name:'Review',role:'CISO · Manager',spans:['review'],children:[]},
  {id:'deliver',name:'Deliver',role:'DevOps · operator',spans:['delivery'],children:[]}
];
const timelineSpans = {
  'memory-read':{name:'Read verified memory',agent:'PM',start:1,end:5,status:'completed',kind:'memory',operation:'read',tool:'read_memory',items:4,bytes:4600,source:'PostgreSQL · lexical retrieval',commit:'8f20c1e'},
  'build-memory':{name:'Retrieve task context',agent:'Developer',start:84,end:89,status:'completed',kind:'memory',operation:'read',tool:'read_memory',items:3,bytes:2900,source:'Project index + verified facts',commit:'8f20c1e'},
  'memory-write':{name:'Write lesson proposal',agent:'Developer',start:171,end:176,status:'completed',kind:'memory',operation:'write',tool:'propose_memory',items:1,bytes:480,source:'Run 042 · implementation observation',commit:'8f20c1e',memory_state:'proposed · not verified'},

  plan:{name:'Scope & plan',agent:'PM',start:0,end:28,status:'completed',kind:'phase',tokens:2100},
  context:{name:'Read repository context',agent:'PM',start:0,end:8,status:'completed',kind:'tool',tool:'read_context'},
  planner:{name:'Plan invocation',agent:'Manager',start:8,end:28,status:'completed',kind:'agent',tokens:2100},
  spec:{name:'Acceptance contract',agent:'PM',start:28,end:58,status:'completed',kind:'phase',tokens:2850},
  requirements:{name:'Define acceptance',agent:'PM',start:28,end:58,status:'completed',kind:'agent',tokens:2850},
  design:{name:'Interaction spec',agent:'Designer',start:58,end:83,status:'completed',kind:'phase',tokens:1900},
  designer:{name:'Design invocation',agent:'Designer',start:58,end:83,status:'completed',kind:'agent',tokens:1900},
  developer:{name:'Implement · attempt 1',agent:'Developer',start:83,end:178,status:'completed',kind:'agent',tokens:8700},
  read:{name:'Read checkout.ts',agent:'Developer',start:89,end:101,status:'completed',kind:'tool',tool:'read_file'},
  edit:{name:'Edit validation branch',agent:'Developer',start:117,end:133,status:'completed',kind:'tool',tool:'edit_source'},
  repair:{name:'Repair · attempt 2',agent:'Developer',start:178,end:212,status:'completed',kind:'agent',tokens:2870,alternative:true},
  'check-failed':{name:'Regression failed',agent:'QA',start:138,end:178,status:'failed',kind:'phase',error:'CHECK_FAILED'},
  qa:{name:'Verify · attempt 2',agent:'QA',start:212,end:252,status:'running',kind:'phase'},
  'test-failed':{name:'node --test · exit 1',agent:'QA',start:145,end:178,status:'failed',kind:'tool',tool:'execute',error:'CHECK_FAILED'},
  'test-running':{name:'node --test · running',agent:'QA',start:214,end:252,status:'running',kind:'tool',tool:'execute'},
  review:{name:'Await verified snapshot',agent:'Manager',start:252,end:300,status:'pending',kind:'phase'},
  delivery:{name:'Await review & gates',agent:'DevOps',start:252,end:300,status:'pending',kind:'phase'}
};
const clock = seconds => `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;
const elapsedLabel = span => span.status==='pending'?'Not started':`${span.end-span.start} s${span.status==='running'?' so far':''}`;
function timelineBar(id, child=false){const span=timelineSpans[id];return `<button type="button" class="time-span span-${span.status} ${span.kind==='tool'?'tool-span':span.kind==='memory'?'memory-span':''} ${span.alternative?'repair-span':''} ${state.node===id?'is-selected':''}" style="left:${span.start/3}%;width:${(span.end-span.start)/3}%" data-node="${id}" data-time-span="${id}" aria-pressed="${state.node===id}" aria-label="${escape(span.name)} · ${span.agent} · ${span.status} · ${elapsedLabel(span)}"><span>${span.status==='failed'?'× ':span.status==='running'?'◉ ':''}${escape(span.name)}</span>${!child&&span.status!=='pending'?`<small>${elapsedLabel(span)}</small>`:''}</button>`;}
function timelineInspector(){const span=timelineSpans[state.node]||timelineSpans.qa;const id=timelineSpans[state.node]?state.node:'qa';const attempt=span.alternative||id==='qa'||id==='test-running'?2:1;const record={version:1,type:`${span.kind}.status`,run_id:'demo-run-042',step_id:id,attempt,sender:span.agent,recipient:'Manager',correlation_id:`demo-${id}-01`,trace_id:'4d09c37bf1594c479782af720efb2471',span_id:`example-${id}`,payload:{state:span.status,start_seconds:span.status==='pending'?null:span.start,end_seconds:['completed','failed'].includes(span.status)?span.end:null,duration_seconds:span.status==='pending'?null:span.end-span.start,tool:span.tool||null,recorded_tokens:span.tokens??null,error_code:span.error||null,memory:span.kind==='memory'?{operation:span.operation,items:span.items,bytes:span.bytes,source:span.source,source_commit:span.commit,state:span.memory_state||'retrieved · source referenced'}:null}};
  let content='';
  if(state.inspector==='JSON')content=json(record);
  else if(state.inspector==='Logs')content=json([{timestamp:'+02:58',level:span.error?'ERROR':'INFO',source:span.agent,correlation_id:record.correlation_id,message:span.status==='pending'?'No logs: step not started':span.error?'Registered check returned exit code 1':'Step observed; sensitive content excluded'}]);
  else if(state.inspector==='Evals')content=span.status==='pending'?'<p>No evaluations recorded.</p>':`<h3>Acceptance evaluations</h3><ul class="checklist"><li>Empty input regression ${tag(span.error?'Failed':span.status==='running'?'Pending':'Passed',span.error?'red':span.status==='running'?'amber':'green')}</li><li>Existing behavior ${tag(span.status==='running'?'Pending':'Recorded')}</li></ul><p class="footer-note">Illustrative evaluator results, not quality claims about the live factory.</p>`;
  else if(state.inspector==='Trace')content=`<div class="trace-heading">OPENTELEMETRY · EXAMPLE DATA</div><dl class="kv"><dt>Trace ID</dt><dd><code>${record.trace_id}</code></dd><dt>Span ID</dt><dd><code>${record.span_id}</code></dd><dt>Parent</dt><dd><code>run-042 / ${span.kind==='tool'?'agent':'phase'}</code></dd><dt>Status</dt><dd>${span.status==='failed'?'ERROR':span.status==='running'?'UNSET · in progress':span.status==='pending'?'No span emitted':'OK'}</dd></dl>${json({attributes:{'sabre.agent':span.agent,'sabre.attempt':attempt,'sabre.phase':id,'gen_ai.usage.input_tokens':span.tokens??'not reported'}})}<p class="footer-note">Correlation and timing only. No prompts or credentials exported. A real OTel trace viewer will use the recorded trace link.</p>`;
  else if(state.inspector==='Evidence')content=span.status==='pending'?'<p>No evidence or telemetry exists for a step that has not started.</p>':`<div class="message"><strong>Source snapshot</strong><p><code>8f20c1e · checkout-service</code><br>Synthetic evidence for this UI concept.</p></div><ul class="checklist"><li>Result ${tag(span.status==='failed'?'Exit code 1':span.status==='running'?'Awaiting result':'Recorded',span.status==='failed'?'red':'')}</li><li>Artifact <code>demo/${escape(id)}.json</code></li></ul>`;
  else if(span.kind==='memory')content=`<dl class="kv"><dt>Operation</dt><dd>${span.operation==='read'?'Read / retrieval':'Write / proposal'}</dd><dt>Agent</dt><dd>${span.agent}</dd><dt>Store / source</dt><dd>${span.source}</dd><dt>Source commit</dt><dd><code>${span.commit}</code></dd><dt>Items</dt><dd>${span.items}</dd><dt>Context size</dt><dd>${span.bytes.toLocaleString('en-US')} bytes</dd><dt>Validity</dt><dd>${span.memory_state||'Referenced to this source snapshot'}</dd></dl><div class="notice">${span.operation==='read'?'Relevant excerpts only. The full repository is not injected into the prompt.':'Stored as a proposal. It will not become a verified fact without evidence.'}</div>`;
  else content=`<dl class="kv"><dt>Phase / agent</dt><dd>${span.agent}</dd><dt>Type</dt><dd>${span.kind==='tool'?'Deterministic tool call':span.kind==='agent'?'Model invocation':'Project phase'}</dd><dt>Status</dt><dd>${span.status}</dd><dt>Started</dt><dd>${span.status==='pending'?'Not started':`+${clock(span.start)}`}</dd><dt>Duration</dt><dd>${elapsedLabel(span)}</dd><dt>Attempt</dt><dd>${attempt}</dd><dt>Tokens</dt><dd>${span.tokens?span.tokens.toLocaleString('en-US'):'Not applicable / not reported'}</dd></dl>${span.error?`<div class="notice error">${span.error}<br>The check blocked advancement and routed the task back to Developer.</div>`:span.alternative?'<div class="notice">Repair route<br>Triggered by the failed QA check at +02:58. This is a separate attempt.</div>':span.status==='pending'?'<p>Future work is a pending slot, not a measured duration.</p>':'<div class="message"><strong>Recorded handoff</strong><p>Inspect the source snapshot and return typed results with verification evidence.</p></div>'}`;
  return `<header><h2>Inspector</h2>${tag(span.kind.toUpperCase(),span.kind==='tool'?'green':'blue')}</header><h2>${escape(span.name)}</h2><p style="font-size:12px">Click pins this selection. Hover or focus any bar for a quick summary.</p>${tabButtons(['Overview','Evals','Logs','JSON','Evidence','Trace'],state.inspector,'data-inspector')}${content}`;
}
function timelineRunView(){if(!state.expandedPhases)state.expandedPhases=new Set(['build','verify']);return heading('CHECKOUT-SERVICE / PATCH / RUN 042','Fix empty checkout validation','Project phases over time. Expand a phase to inspect agents, invocations and tool calls.',`${tag(state.run==='running'?'Running':state.run,state.run==='running'?'green':'amber')}<button data-action="pause">${state.run==='paused'?'Resume':'Pause'}</button><button class="primary" data-action="new-run">New run</button>`)+(state.scenario==='empty'?emptyView('Your first run starts with a connected project','Choose a provider and repository, then define an outcome and its acceptance checks.','config'):`
  <div class="metrics"><div class="metric"><span>Current phase</span><strong>Verify</strong></div><div class="metric"><span>Elapsed · demo snapshot</span><strong>04:12</strong></div><div class="metric"><span>Recorded tokens</span><strong>18,420</strong><small>/ 100k</small></div><div class="metric"><span>Repair cycles</span><strong>1</strong><small>/ 2</small></div><div class="metric"><span>Subscription cost</span><strong>Unknown</strong></div></div>
  ${state.run==='waiting_input'?`<div class="notice"><strong>Supervisor requests a human decision.</strong> PM found an ambiguous acceptance criterion. Should empty input return an empty result or a validation error?<span class="hitl-meta">Run 042 · Spec phase · question q-7 · plan revision 3 · dependent work blocked</span><div class="actions" style="margin-top:12px"><button data-action="answer-empty">Return an empty result</button><button data-action="answer-error">Return a validation error</button></div></div>`:''}
  <div class="temporal-console"><section class="temporal-panel" aria-label="Project timeline"><div class="time-toolbar"><div><strong>Project timeline</strong><small>Phases → agent invocations → tools</small></div><div class="legend"><span>Agent / phase</span><span class="code">Tool</span><span class="memory-legend">Memory</span><span class="failure">Failed</span><span class="human">Repair</span></div></div>
  <div class="timeline-scroll"><div class="timeline-grid"><div class="time-ruler"><div class="phase-column">PHASE / ACTIVITY</div><div class="ruler-track">${[0,60,120,180,240,300].map(t=>`<span style="left:${t/3}%">${clock(t)}</span>`).join('')}<div class="now-caption" style="left:84%">NOW</div></div></div>
  ${timelinePhases.map((phase,index)=>`<div class="time-row"><div class="phase-column"><button class="phase-toggle" data-phase-toggle="${phase.id}" aria-expanded="${state.expandedPhases.has(phase.id)}" ${phase.children.length?'':'disabled'}><span class="phase-index">${String(index+1).padStart(2,'0')}</span><span><strong>${phase.name}</strong><small>${phase.role}</small></span>${phase.children.length?`<span class="chevron">${state.expandedPhases.has(phase.id)?'⌄':'›'}</span>`:''}</button></div><div class="time-track"><div class="now-line"></div>${phase.spans.map(id=>timelineBar(id)).join('')}</div></div>${state.expandedPhases.has(phase.id)?phase.children.map(id=>`<div class="time-row child-row"><div class="phase-column"><span class="child-kind">${timelineSpans[id].kind==='tool'?'↳ TOOL':timelineSpans[id].kind==='memory'?'↳ MEMORY':'↳ AGENT'}</span><span>${escape(timelineSpans[id].tool||timelineSpans[id].agent)}</span></div><div class="time-track"><div class="now-line"></div>${timelineBar(id,true)}</div></div>`).join(''):''}`).join('')}
  <div class="time-row branch-row"><div class="phase-column">ALTERNATIVE ROUTE</div><div class="time-track"><div class="repair-link" style="left:${178/3}%;width:${34/3}%">↳ QA failed → Build → Verify</div></div></div></div></div>
  <div class="time-footer"><span>Pending slots show dependencies, not predicted duration.</span><span>Demo clock frozen at +04:12</span></div></section><aside class="inspector" aria-label="Step inspector">${timelineInspector()}</aside></div>
  <div class="feed"><div class="feed-head"><span>Activity <span class="muted">· messages and telemetry</span></span><div class="actions"><button data-action="question">Preview a question</button><button data-action="delivery">Preview delivery</button></div></div><div class="feed-row"><time>+03:32</time><span class="mono">QA</span><span>Verification attempt 2 · execute · node --test</span><small>Running</small></div><div class="feed-row"><time>+02:58</time><span class="mono">Manager</span><span>CHECK_FAILED → repair routed to Developer</span><small>Branch</small></div><div class="feed-row"><time>+02:18</time><span class="mono">Developer</span><span>Snapshot handed to QA · independent check started</span><small>Message</small></div></div><p class="footer-note">Synthetic design data. Timing, repair branches and OpenTelemetry identifiers illustrate the experience; no runtime is connected.</p>`);}
document.addEventListener('click',event=>{const button=event.target.closest('[data-phase-toggle]');if(!button||button.disabled)return;const id=button.dataset.phaseToggle;state.expandedPhases.has(id)?state.expandedPhases.delete(id):state.expandedPhases.add(id);render();});
function showSpanTip(element){const span=timelineSpans[element.dataset.timeSpan];if(!span)return;let tip=document.getElementById('span-tooltip');if(!tip){tip=document.createElement('div');tip.id='span-tooltip';tip.role='tooltip';document.body.append(tip);}tip.innerHTML=`<strong>${escape(span.name)}</strong><span>${span.agent} · ${span.status} · ${elapsedLabel(span)}</span><small>${span.tokens?span.tokens.toLocaleString('en-US')+' recorded tokens':'No model token measurement'} · Click to inspect</small>`;const rect=element.getBoundingClientRect();tip.hidden=false;tip.style.left=Math.max(10,Math.min(rect.left,innerWidth-310))+'px';tip.style.top=Math.max(10,rect.top-95)+'px';}
document.addEventListener('mouseover',event=>{const bar=event.target.closest('[data-time-span]');if(bar)showSpanTip(bar);else document.getElementById('span-tooltip')?.setAttribute('hidden','');});
document.addEventListener('focusin',event=>{if(event.target.matches('[data-time-span]'))showSpanTip(event.target);});
document.addEventListener('focusout',()=>document.getElementById('span-tooltip')?.setAttribute('hidden',''));
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.getElementById('span-tooltip')?.setAttribute('hidden','');});
